Let me write it cleanly:

```go
package bottlesong

import (
	"fmt"
	"strings"
	"unicode"
)

var numberWords = map[int]string{
	0: "no", 1: "one", 2: "two", 3: "three", 4: "four",
	5: "five", 6: "six", 7: "seven", 8: "eight", 9: "nine", 10: "ten",
}

// bottles returns the count phrase, e.g. "ten green bottles" or "one green bottle".
func bottles(count int) string {
	plural := "s"
	if count == 1 {
		plural = ""
	}
	return fmt.Sprintf("%s green bottle%s", numberWords[count], plural)
}

func title(s string) string {
	r := []rune(s)
	r[0] = unicode.ToUpper(r[0])
	return string(r)
}

func Recite(startBottles, takeDown int) []string {
	verses := make([][]string, 0, takeDown)
	for i := 0; i < takeDown; i++ {
		n := startBottles - i
		verses = append(verses, []string{
			fmt.Sprintf("%s hanging on the wall,", title(bottles(n))),
			fmt.Sprintf("%s hanging on the wall,", title(bottles(n))),
			"And if one green bottle should accidentally fall,",
			fmt.Sprintf("There'll be %s hanging on the wall.", bottles(n-1)),
		})
	}
	var lines []string
	for i, v := range verses {
		if i > 0 {
			lines = append(lines, "")
		}
		lines = append(lines, v...)
	}
	return lines
}
```

